  <li><strong>ม.40(6) วิชาชีพอิสระ 6 วิชาชีพ:</strong> แพทย์ หักเหมา 60% / กฎหมาย บัญชี วิศวกรรม สถาปัตยกรรม ประณีตศิลป์ หักเหมา 30%</li>
