      {
        heading: "🚗 ตัวอย่างชีวิตจริง (Real-Life Calculation Case Study)",
        content: `<p style="margin-bottom:10px;"><strong>โจทย์:</strong> นายสมชาย เป็นพนักงานบริษัท มีเงินเดือน ม.40(1) ปีละ 600,000 บาท จ่ายประกันสังคม 9,000 บาท จ่ายประกันชีวิต 30,000 บาท นายสมชายต้องเสียภาษีเท่าไร?</p>
<ol class="clean-numbered-list">
  <li><strong>เงินได้พึงประเมิน ม.40(1):</strong> 600,000 บาท</li>
  <li><strong>หักค่าใช้จ่ายเหมา 50%:</strong> 50% ของ 600,000 = 300,000 บาท แต่ติดเพดานกฎหมายสูงสุดไม่เกิน 100,000 บาท คงเหลือ = 500,000 บาท</li>
  <li><strong>หักค่าลดหย่อน:</strong> ส่วนตัว 60,000 + ประกันสังคม 9,000 + ประกันชีวิต 30,000 = 99,000 บาท</li>
  <li><strong>คำนวณเงินได้สุทธิ:</strong> 500,000 - 99,000 = 401,000 บาท</li>
  <li><strong>คำนวณภาษีตามอัตราก้าวหน้า:</strong> (0-150k ยกเว้น = 0) + (150k-300k เสีย 5% = 7,500) + (300k-401k ส่วนเกิน 101k เสีย 10% = 10,100) -> <strong>รวมภาษีชำระ = 17,600 บาท</strong></li>
</ol>`
      }
