  <li><strong>เงินเพิ่ม (Surcharges/Interest):</strong> ดอกเบี้ยจากการ <em>"จ่ายเงินช้า"</em> คิดอัตราร้อยละ 1.5 ต่อเดือน (เศษของเดือนคิดเป็น 1 เดือน) มีเพดานสูงสุดไม่เกินตัวเงินภาษี</li>
