        fullText: `มาตรา 21 ถ้าผู้มีหน้าที่ยื่นแบบแสดงรายการยื่นแบบไว้ไม่ถูกต้องหรือไม่ครบถ้วน เจ้าพนักงานประเมินมีอำนาจประเมินภาษีตามหลักฐานที่ตรวจสอบได้`
