        fullText: `มาตรา 77/1 ในหมวดนี้

"ขาย" หมายความว่า โอนกรรมสิทธิ์ในสินค้าเพื่อได้ค่าตอบแทน ไม่ว่าสัญญาจำหน่าย จ่าย โอน จะมีประโยชน์ตอบแทนหรือไม่

"บริการ" หมายความว่า การรับทำงานใดๆ ให้ โดยได้รับประโยชน์ตอบแทนซึ่งมิใช่การขายสินค้า

"สินค้า" หมายความว่า ทรัพย์สินที่มีรูปร่างและไม่มีรูปร่าง ที่มีไว้เพื่อขาย สั่ง หรือนำเข้ามาเพื่อขาย...`
