        fullText: `มาตรา 78 ความรับผิดในการเสียภาษีมูลค่าเพิ่มที่เกิดจากการขายสินค้า ให้เกิดขึ้นเมื่อมีการส่งมอบสินค้า เว้นแต่กรณีที่มีการโอนกรรมสิทธิ์ สินค้า ชำระราคา หรือออกใบกำกับภาษีก่อนการส่งมอบ ให้ความรับผิดเกิดขึ้นเมื่อมีการกระทำนั้นๆ`
