        fullText: `มาตรา 79 ฐานภาษีสำหรับการขายสินค้าหรือการให้บริการ ได้แก่ มูลค่าทั้งหมดที่ผู้ประกอบการได้รับหรือพละกำลังจะได้รับจากการขายสินค้าหรือการให้บริการ รวมทั้งภาษีสรรพสามิตถ้ามี (แต่ไม่รวมภาษีมูลค่าเพิ่ม)`
