        heading: "💡 สรุปภาษาบ้านๆ: Tax Point และโครงสร้าง VAT/SBT/อากร",
        content: `<p>จุดเกิดความรับผิดทางภาษี (Tax Point) คือเข็มทิศสำคัญที่สรรพากรใช้ตรวจว่า ท่านต้องออกใบกำกับภาษีและนำส่ง VAT เมื่อใด:</p>
<ul class="clean-list">
  <li><strong>ขายสินค้า:</strong> Tax Point เกิดเมื่อ <em>"ส่งมอบสินค้า"</em> (แม้ยังไม่ได้เงิน ก็ต้องเสีย VAT แล้ว!)</li>
  <li><strong>ให้บริการ:</strong> Tax Point เกิดเมื่อ <em>"ได้รับชำระเงิน"</em> หรือ <em>"ออกใบกำกับภาษี"</em></li>
</ul>`
