        heading: "มาตรา 86/9 & 86/10 (ใบลดหนี้ Credit Note & ใบเพิ่มหนี้ Debit Note)",
        content: `<ul class="clean-list">
  <li><strong>ใบลดหนี้ (Credit Note - ม.86/9):</strong> ออกเมื่อสินค้าชำรุด, คืนสินค้า, คำนวณราคาสินค้าเกินไป -> นำ VAT ไป <strong>หักออกจากภาษีขาย</strong> ในเดือนที่ออกใบลดหนี้</li>
  <li><strong>ใบเพิ่มหนี้ (Debit Note - ม.86/10):</strong> ออกเมื่อคำนวณราคาสินค้าขาดไป, จำนวนสินค้าเกิน -> นำ VAT ไป <strong>รวมเป็นภาษีขาย</strong> ในเดือนที่ออกใบเพิ่มหนี้</li>
</ul>`
